import { PlantData, PlantKind } from "./types";

// Fictional plant deck: numbers 3 to 50, generated by formula (not the official cards).
// A plant costs its number to buy. Higher numbers power more cities and need more fuel.
export const PLANT_NUMBERS: number[] = [];
for (let n = 3; n <= 50; n++) PLANT_NUMBERS.push(n);

export function plantData(n: number): PlantData {
  const r = n % 5;
  let kind: PlantKind;
  if (r === 0) kind = "coal";
  else if (r === 1) kind = "eco";
  else if (r === 2) kind = "oil";
  else if (r === 3) kind = "garbage";
  else kind = n >= 20 ? "uranium" : "eco";

  const cities = 1 + Math.floor((n - 3) / 7);
  let inputs = 0;
  if (kind === "uranium") inputs = 1 + Math.floor((n - 20) / 10);
  else if (kind !== "eco") inputs = 1 + Math.floor((n - 3) / 12);

  return { number: n, kind, inputs, cities };
}

// Fuel a plant can store: two rounds' worth.
export function plantCapacity(data: PlantData): number {
  return data.inputs * 2;
}
